'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const e=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const N=n=>new Intl.NumberFormat('pl-PL',{maximumFractionDigits:1}).format(Number(n)||0);
const iso=d=>`${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;
const shift=(s,n)=>{const d=new Date(s+'T12:00:00');d.setDate(d.getDate()+n);return iso(d)};
const today=()=>iso(new Date()), meals=['Śniadanie','Obiad','Kolacja'], seasons=['wiosna','lato','jesień','zima'];
const forms=[['fresh','Świeże'],['frozen','Mrożone'],['canned','Puszka'],['jar','Słoik'],['dried','Suszone']];
const icons={menu:'M4 6h16M4 12h16M4 18h16',home:'m3 10 9-7 9 7M5 9v12h14V9M9 21v-8h6v8',book:'M4 3h7l1 2 1-2h7v17h-7l-1 1-1-1H4zM12 5v16',calendar:'M4 5h16v16H4zM8 3v4m8-4v4M4 10h16',cart:'M2 3h3l3 12h10l3-8H6M9 20h.01M18 20h.01',plus:'M12 4v16M4 12h16',sun:'M12 3v2m0 14v2M3 12h2m14 0h2M5 5l2 2m10 10 2 2M5 19l2-2M17 7l2-2M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0',heart:'M20 5c-3-3-7 0-8 2-1-2-5-5-8-2-5 5 8 15 8 15S25 10 20 5',cook:'M7 9a4 4 0 1 1 3-6 4 4 0 0 1 7 3 3 3 0 0 1 0 6v8H7V9m0 7h10',back:'m15 5-7 7 7 7',search:'M15 15l6 6M17 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0'};
const icon=k=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[k]||icons.book}"/></svg>`;
const btn=(text,a,id='',cls='dm-btn')=>`<button type="button" class="${cls}" data-a="${a}" data-id="${e(id)}">${text}</button>`;
const panel=s=>`<section class="dm-panel dm-space">${s}</section>`;
const empty=s=>`<div class="dm-no-items">${s}</div>`;
const photo=r=>r.image_path&&/^\/media\/[a-f0-9]{32}\.(jpg|png|webp)$/.test(r.image_path)?`<img src="${e(r.image_path)}" alt="${e(r.name)}" loading="lazy">`:`<div class="dm-photo-fallback">${icon('cook')}</div>`;
let S={profiles:[],recipes:[],meals:[],diary:[],weights:[],foods:[],rules:[],lists:[]}, day=today(), pid=Number(localStorage.getItem('profile'))||0, page='home', recipeId=null, search='', collection='', month=false, listId=null, shopping=null, proposal=null, detailPortions=1, formCallback=null, importKind='', cookId=null;
const p=()=>S.profiles.find(x=>x.id===pid)||S.profiles[0]||{};
const recipe=id=>S.recipes.find(x=>x.id==id);
const event=id=>S.meals.find(x=>x.id===id);
const dayMeals=()=>S.meals.filter(m=>m.date===day);
function toast(t){$('#toast').textContent=t;clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').textContent='',5000)}
async function api(path,data,method){const r=await fetch(path,{method:method||(data?'POST':'GET'),headers:data?{'Content-Type':'application/json'}:{},body:data?JSON.stringify(data):undefined});let d;try{d=await r.json()}catch{throw Error('Serwer zwrócił nieprawidłową odpowiedź ('+r.status+')')}if(!r.ok){if(r.status===401&&path!='/api/login')login();throw Error(d.error||'Błąd '+r.status)}return d}
const post=(path,d)=>api('/api/v1/'+path,d);
async function load(){S=await api('/api/v1/state?date='+day);if(!S.profiles.some(x=>x.id===pid))pid=S.profiles[0]?.id||0;if(page==='shopping'&&listId)shopping=await api('/api/v1/shopping?id='+listId);render()}
function go(where){page=where;$('#dialog').close();render();window.scrollTo({top:0,behavior:'instant'})}
function head(title,action=''){return `<div class="dm-head"><h1>${e(title)}</h1>${action}</div>`}
function field(label,name,value='',type='text',extra=''){return `<label class="dm-field">${e(label)}<input name="${name}" type="${type}" value="${e(value??'')}" ${extra}></label>`}
function area(label,name,value='',help=''){return `<label class="dm-field wide">${e(label)}<textarea name="${name}">${e(value)}</textarea>${help?`<small>${e(help)}</small>`:''}</label>`}
function select(label,name,options,value){return `<label class="dm-field">${e(label)}<select name="${name}">${options.map(o=>{const [v,t]=Array.isArray(o)?o:[o,o];return `<option value="${e(v)}" ${String(v)===String(value)?'selected':''}>${e(t)}</option>`}).join('')}</select></label>`}
function checks(label,name,options,values=[]){return `<fieldset class="dm-field wide"><legend>${e(label)}</legend><div class="dm-checkboxes">${options.map(o=>{const[v,t]=Array.isArray(o)?o:[o,o];return `<label><input type="checkbox" name="${name}" value="${e(v)}" ${values.map(String).includes(String(v))?'checked':''}>${e(t)}</label>`}).join('')}</div></fieldset>`}
function checkbox(label,name,checked){return `<label class="dm-choice"><input type="checkbox" name="${name}" ${checked?'checked':''}>${e(label)}</label>`}
function sheet(title,html){$('#dialog-title').textContent=title;$('#dialog-body').innerHTML=html;if(!$('#dialog').open)$('#dialog').showModal();$('#dialog').scrollTop=0}
function form(title,html,callback,label='Zapisz'){formCallback=callback;sheet(title,`<form id="editor"><div class="dm-form-grid">${html}</div><div data-error class="dm-error" role="alert"></div><button class="dm-btn full" type="submit">${label}</button></form>`)}
function totalPlan(profile=p()){return dayMeals().reduce((a,m)=>a+Number(m.recipe.calories||0)*Number(m.portions[String(profile.id)]||0),0)}
function balance(value,profile=p()){const target=Number(profile.calories||0),tol=profile.tolerance_type==='percent'?target*Number(profile.tolerance_value??5)/100:Number(profile.tolerance_value||0);return{target,tol,low:Math.max(0,target-tol),high:target+tol,accepted:!target||Math.abs(value-target)<=tol}}
function balanceCard(){const value=totalPlan(),b=balance(value),consumed=S.diary.filter(x=>x.profile_id===p().id&&x.status==='eaten').reduce((a,x)=>a+Number(x.calories),0);return panel(`<div class="dm-between"><span class="dm-eyebrow">Bilans · ${e(p().name)}</span><span class="dm-badge">${b.target?(b.accepted?'W zakresie celu':'Poza zakresem'):'Cel wyłączony'}</span></div><div class="dm-balance dm-space"><strong>${N(value)} kcal</strong><span class="dm-muted">cel ${b.target?N(b.target):'—'}</span><div class="dm-track"><i style="width:${b.target?Math.min(100,value/b.target*100):0}%"></i></div><p class="dm-muted">Zaplanowano · zjedzono ${N(consumed)} kcal</p>${b.target?`<p class="dm-muted">Zakres ${N(b.low)}–${N(b.high)} kcal · tolerancja ±${N(b.tol)} kcal · różnica ${value-b.target>=0?'+':''}${N(value-b.target)} kcal</p>`:''}</div>`)}
function calendar(){const d=new Date(day+'T12:00:00'),start=month?new Date(d.getFullYear(),d.getMonth(),1):new Date(d);start.setDate(start.getDate()-(start.getDay()+6)%7);const count=month?42:7;return `<section class="dm-calendar"><div class="dm-calendar-head">${btn('‹','date-shift',month?'month:-1':-7,'dm-icon')}<strong>${e(d.toLocaleDateString('pl-PL',{month:'long',year:'numeric'}))}</strong>${btn('›','date-shift',month?'month:1':7,'dm-icon')}</div><div class="dm-calendar-grid">${['Pn','Wt','Śr','Cz','Pt','So','Nd'].map(x=>`<span class="dm-weekday">${x}</span>`).join('')}${Array.from({length:count},(_,i)=>{const s=shift(iso(start),i),v=new Date(s+'T12:00:00');return `<button class="dm-date ${s===day?'selected':''}" data-a="date" data-id="${s}"><span>${v.getDate()}</span><i class="dm-dots">${S.meals.filter(m=>m.date===s&&!m.profile_id).map(()=>'<i></i>').join('')}</i></button>`}).join('')}</div></section>`}
function mealCard(m,diary=false){const amount=Number(m.portions[String(p().id)]||0),kcal=Number(m.recipe.calories||0)*amount,cls=['breakfast','lunch','dinner'][meals.indexOf(m.meal)]||'snack',logged=S.diary.find(x=>x.source_meal_id===m.id&&x.profile_id===p().id);return `<article class="dm-meal-wrap"><button class="dm-meal ${cls}" data-a="detail" data-id="${m.recipe_id}">${photo(m.recipe)}<div><span class="dm-tag ${cls}">${e(m.meal)}${m.profile_id?' · '+e(S.profiles.find(p=>p.id===m.profile_id)?.name||''):''}</span><strong>${e(m.recipe.name)}</strong><div class="dm-note">${N(amount)} porcji dla Ciebie · gotowanie ${e(m.prepare_date)}</div><small class="dm-muted">${logged?({eaten:'Zjedzone',skipped:'Pominięte',planned:'Zaplanowane'}[logged.status]):m.prepared?'Przygotowane':'Do przygotowania'}</small></div><span class="dm-kcal-mini">${N(kcal)} kcal</span></button><div class="dm-actions">${diary?btn('✓ Zjedzone','eat',m.id,'dm-btn soft')+btn('Pomiń','skip',m.id,'dm-btn ghost'):btn('Zamień','swap',m.id,'dm-btn soft')+btn('Gotowanie','cook-batch',m.id,'dm-btn ghost')+btn('Usuń','delete-meal',m.id,'dm-btn ghost')}</div></article>`}
const desktopNav=[
 ['Codziennie',[['home','home','Start'],['planner','calendar','Plan rodzinny'],['diary','book','Dziennik'],['shopping','cart','Zakupy']]],
 ['Twoja kuchnia',[['recipes','book','Przepisy'],['collections','heart','Kolekcje'],['prep','cook','Przygotowanie'],['products','book','Produkty i miary']]],
 ['Rodzina',[['household','home','Domownicy'],['goals','heart','Cele żywieniowe'],['progress','calendar','Masa i postępy'],['rules','calendar','Reguły generatora']]]
];
function sidebar(){return `<div class="dm-sidebar-brand"><span class="dm-sidebar-logo">${icon('cook')}</span><div><strong>Domowe Menu</strong><small>Twoja rodzinna kuchnia</small></div></div>${btn(icon('plus')+' Dodaj do kuchni','nav','add','dm-btn full dm-sidebar-add')}<nav aria-label="Sekcje aplikacji">${desktopNav.map(([title,items])=>`<section class="dm-nav-group"><p>${title}</p>${items.map(([id,i,t])=>`<button type="button" data-a="nav" data-id="${id}" class="dm-side-link ${page===id||(page==='detail'&&id==='recipes')?'active':''}" ${page===id?'aria-current="page"':''}>${icon(i)}<span>${t}</span></button>`).join('')}</section>`).join('')}</nav><div class="dm-sidebar-footer">${btn(icon('menu')+' Ustawienia i kopie','nav','settings','dm-side-link '+(page==='settings'?'active':''))}<small>Domowe Menu · ${e(S.version)}</small></div>`}
function pageTitle(){return desktopNav.flatMap(x=>x[1]).find(x=>x[0]===page)?.[2]||({detail:'Szczegóły przepisu',cook:'Gotowanie',settings:'Ustawienia i kopie'}[page])||'Twoja kuchnia'}
function desktopCalendar(){
 const selected=new Date(day+'T12:00:00'),first=month?new Date(selected.getFullYear(),selected.getMonth(),1):new Date(selected);
 first.setDate(first.getDate()-(first.getDay()+6)%7);
 const start=iso(first),count=month?42:7;
 return `<section class="dm-desktop-planner" aria-label="${month?'Miesięczny':'Tygodniowy'} plan rodzinny"><div class="dm-board-toolbar"><div>${btn('‹','date-shift',month?'month:-1':-7,'dm-btn ghost')}<strong>${e(month?selected.toLocaleDateString('pl-PL',{month:'long',year:'numeric'}):new Date(start+'T12:00:00').toLocaleDateString('pl-PL',{day:'numeric',month:'long'})+' – '+new Date(shift(start,6)+'T12:00:00').toLocaleDateString('pl-PL',{day:'numeric',month:'long',year:'numeric'}))}</strong>${btn('›','date-shift',month?'month:1':7,'dm-btn ghost')}</div>${btn('Dzisiaj','date',today(),'dm-btn soft')}</div><div class="dm-board-scroll" tabindex="0" aria-label="Przewijany kalendarz posiłków"><div class="dm-week-board ${month?'is-month':''}">${Array.from({length:count},(_,i)=>{
 const date=shift(start,i),d=new Date(date+'T12:00:00'),rows=S.meals.filter(m=>m.date===date),total=rows.reduce((a,m)=>a+Number(m.recipe.calories||0)*Number(m.portions[p().id]||0),0);
 return `<section class="dm-board-day ${date===day?'selected':''} ${date===today()?'today':''} ${month&&d.getMonth()!==selected.getMonth()?'outside':''}"><button type="button" class="dm-board-date" data-a="date" data-id="${date}" ${date===day?'aria-pressed="true"':'aria-pressed="false"'}><span>${e(d.toLocaleDateString('pl-PL',{weekday:'short'}))}</span><strong>${d.getDate()}</strong><small>${N(total)} kcal</small></button><div class="dm-board-slots">${meals.map((meal,j)=>{
 const m=rows.find(x=>x.meal===meal&&!x.profile_id);
 return `<div class="dm-board-slot meal-${j}"><span class="dm-slot-label">${e(meal)}</span>${m?`<button type="button" class="dm-board-recipe" data-a="week-meal" data-id="${e(m.id)}">${month?'':photo(m.recipe)}<strong>${e(m.recipe.name)}</strong><small>${N(Number(m.recipe.calories||0)*Number(m.portions[p().id]||0))} kcal${m.prepared?' · gotowe':''}</small></button>`:btn('＋ Dodaj','plan-slot',date+'|'+meal,'dm-slot-add')}</div>`;
 }).join('')}${rows.filter(x=>x.profile_id).map(m=>`<button type="button" class="dm-board-snack" data-a="week-meal" data-id="${e(m.id)}"><span>Przekąska · ${e(S.profiles.find(x=>x.id===m.profile_id)?.name||'')}</span><strong>${e(m.recipe.name)}</strong></button>`).join('')}</div></section>`;
 }).join('')}</div></div><p class="dm-muted dm-board-caption">Wartości kalorii dotyczą profilu ${e(p().name)}. Główne dania są wspólne dla rodziny.</p></section>`;
}

function render(){document.body.dataset.auth="true";document.body.dataset.page=page;$('#sidebar').innerHTML=sidebar();const profile=p();$('#top').innerHTML=`<div>${btn(icon('menu'),'menu','','dm-icon')}<span class="dm-brand">Domowe Menu</span><span class="dm-desktop-current">${e(pageTitle())}</span></div><div><span class="dm-desktop-label">Domownik</span>${btn(icon('sun'),'theme','','dm-icon')}<select id="profile-select" class="dm-profiles" aria-label="Domownik">${S.profiles.map(x=>`<option value="${x.id}" ${x.id===profile.id?'selected':''}>${e(x.name)}</option>`).join('')}</select></div>`;$('#nav').innerHTML=[['home','home','Start'],['recipes','book','Przepisy'],['add','plus','Dodaj'],['planner','calendar','Planer'],['shopping','cart','Zakupy']].map(([id,i,t])=>`<button data-a="nav" data-id="${id}" class="${page===id?'active ':''}${id==='add'?'dm-add':''}" aria-label="${t}">${icon(i)}${id==='add'?'':`<span>${t}</span>`}</button>`).join('');const views={home:homeView,recipes:recipesView,detail:detailView,planner:plannerView,diary:diaryView,shopping:shoppingView,household:householdView,goals:goalsView,progress:progressView,products:productsView,rules:rulesView,settings:settingsView,prep:prepView,collections:collectionsView,cook:cookView};$('#main').innerHTML=(views[page]||homeView)()}
function homeView(){const rows=dayMeals().filter(m=>!m.profile_id||m.profile_id===p().id);return `<section class="dm-hero"><div class="dm-hero-content"><p>Wspólnie przy stole</p><h1>Co dziś gotujemy?</h1><p>Te same dania, porcje i przekąski dopasowane do rodziny.</p>${btn('Zaplanuj kolejny tydzień','generator')}</div><div class="dm-hero-date">${e(new Date(day+'T12:00:00').toLocaleDateString('pl-PL',{weekday:'long',day:'numeric',month:'long'}))}</div></section><div class="dm-dashboard"><section class="dm-dashboard-meals"><div class="dm-section"><h2>Posiłki na ${e(day)}</h2>${btn('Otwórz dziennik','nav','diary','dm-link')}</div><div class="dm-stack dm-home-meals">${rows.map(m=>mealCard(m,true)).join('')||empty('Plan jest jeszcze pusty. Dodaj przepisy, a następnie ułóż pierwszy tydzień.')}</div></section><aside class="dm-dashboard-summary">${balanceCard()}${panel(`<h2>Rodzinna kuchnia</h2><div class="dm-home-stats"><div><strong>${S.recipes.filter(r=>!r.archived).length}</strong><span>przepisów</span></div><div><strong>${S.profiles.length}</strong><span>domowników</span></div></div><div class="dm-stack dm-space">${btn('Otwórz plan rodzinny','nav','planner','dm-btn soft')}${btn('Przejdź do zakupów','nav','shopping','dm-btn ghost')}</div>`)}</aside></div>${!S.recipes.length?panel(`<h2>Zacznij od swojej kuchni</h2><p class="dm-muted dm-space">Dodaj pierwszy przepis lub zaimportuj przepisy z kopii Mealie. Potem uzupełnij domowników i cele.</p><div class="dm-actions">${btn('Dodaj przepis','recipe-new')}${btn('Import Mealie','import-mealie','','dm-btn ghost')}</div>`):''}`}
function recipesView(){const filtered=S.recipes.filter(r=>(collection==='Archiwum'?r.archived:!r.archived)&&(!collection||collection==='Archiwum'||(collection==='Ulubione'?r.favorite:(r.tags||'').split(',').map(s=>s.trim()).includes(collection)))&&`${r.name} ${r.tags} ${r.category} ${r.meal_types.join(' ')}`.toLocaleLowerCase('pl').includes(search.toLocaleLowerCase('pl')));return head(collection||'Twoje przepisy',btn('＋','recipe-new','','dm-icon'))+`<label class="dm-searchbox">${icon('search')}<input id="search" placeholder="Szukaj dania, tagu, kategorii…" value="${e(search)}" aria-label="Szukaj przepisu"></label><div class="dm-categories">${['','Ulubione',...meals,'Przekąska','Archiwum'].map(t=>btn(t||'Wszystkie','filter',t,'dm-pill '+(collection===t?'active':''))).join('')}</div><div class="dm-recipes">${filtered.map(r=>`<button class="dm-recipe" data-a="detail" data-id="${r.id}"><div class="dm-recipe-photo">${photo(r)}${r.favorite?'<span class="dm-like">♥</span>':''}</div><div class="dm-recipe-text"><strong>${e(r.name)}</strong><small>${N(r.calories)} kcal / porcja · ${r.active_minutes===null?'czas niepodany':N(r.active_minutes)+' min pracy'}</small><span class="dm-badge">${e(r.category)}</span></div></button>`).join('')}</div>${filtered.length?'':empty('Brak przepisów. Dodaj własny lub użyj importu w menu.')}`}
function detailView(){const r=recipe(recipeId);if(!r)return empty('Przepis nie jest dostępny.');const ratio=detailPortions/Number(r.servings||1);return `<div class="dm-recipe-detail"><section class="dm-recipe-overview"><div class="dm-detail-photo">${photo(r)}${btn('‹','nav','recipes','dm-icon')}</div><h1 class="dm-recipe-title">${e(r.name)}</h1><div class="dm-round-actions">${[['Gotuj','cook-recipe','cook'],['Planuj','plan-recipe','calendar'],[r.favorite?'Ulubiony':'Ulubione','favorite','heart'],['Edytuj','recipe-edit','book']].map(([t,a,i])=>`<button data-a="${a}" data-id="${r.id}"><span>${icon(i)}</span>${t}</button>`).join('')}</div><p class="dm-description">${e(r.notes)}</p>${panel(`<div class="dm-between"><strong>${N(r.calories)} kcal / porcja</strong><span class="dm-muted">${N(r.active_minutes)} min pracy · ${N(r.total_minutes)} min łącznie</span></div><div class="dm-macros">${['protein','carbs','fat'].map((k,i)=>`<span>${['Białko','Węgle','Tłuszcz'][i]} <b>${N(r[k])} g</b></span>`).join('')}</div>`)}</section><section class="dm-recipe-content"><div class="dm-section"><h2>Składniki</h2><div class="dm-flex">${btn('−','portion',-.5,'dm-icon')}<span>${N(detailPortions)} porcji</span>${btn('＋','portion',.5,'dm-icon')}</div></div>${panel(r.ingredients.map(i=>`<div class="dm-ingredient"><div>${e(i.name)}<small>${e(forms.find(x=>x[0]===(i.form||'fresh'))?.[1]||'')}${i.grams_each?' · '+N(i.qty*i.grams_each*ratio)+' g':''}</small></div><span>${N(i.qty*ratio)} ${e(i.unit)}</span></div>`).join('')||empty('Brak składników'))}<div class="dm-section"><h2>Przygotowanie</h2></div>${panel((r.instructions||'').split('\n').filter(Boolean).map((s,i)=>`<p class="dm-listrow"><b>${i+1}.</b> ${e(s)}</p>`).join('')||empty('Brak instrukcji'))}<div class="dm-actions dm-space">${btn(r.archived?'Przywróć z archiwum':'Archiwizuj przepis','archive',r.id,'dm-btn ghost')}${btn('Drukuj','print','','dm-btn ghost')}</div></section></div>`}
function plannerView(){return head('Plan rodzinny',btn('Generuj plan','generator'))+`<div class="dm-plan-tools">${btn(month?'Widok tygodnia':'Widok miesiąca','calendar-mode','','dm-btn ghost')}${btn('＋ Posiłek','plan-new','','dm-btn soft')}${btn('Kopiuj poprzedni dzień','copy-day','','dm-btn ghost')}${btn('Reguły generatora','nav','rules','dm-btn ghost')}</div><div class="dm-mobile-calendar">${calendar()}</div>${desktopCalendar()}<div class="dm-day-detail"><section><div class="dm-section"><h2>Posiłki · ${e(day)}</h2></div><div class="dm-stack dm-selected-meals">${dayMeals().map(m=>mealCard(m)).join('')||empty('Na ten dzień nie ma posiłków.')}</div></section><aside>${balanceCard()}</aside></div>`}
function diaryView(){const rows=S.diary.filter(x=>x.profile_id===p().id),tot=key=>rows.filter(x=>x.status==='eaten').reduce((a,x)=>a+Number(x[key]||0),0);return head('Dziennik dnia',btn('＋ Poza planem','diary-new'))+`<div class="dm-diary-date">${field('Dzień','diary-date',day,'date')}</div><div class="dm-diary-layout"><section><div class="dm-section"><h2>Posiłki z planu</h2></div><div class="dm-stack">${dayMeals().filter(m=>Number(m.portions[p().id])>0).map(m=>mealCard(m,true)).join('')||empty('Brak zaplanowanych posiłków.')}</div></section><aside>${panel(`<span class="dm-eyebrow">Zjedzono · ${e(p().name)}</span><h2>${N(tot('calories'))} kcal</h2><div class="dm-macros"><span>Białko ${N(tot('protein'))} g</span><span>Węgle ${N(tot('carbs'))} g</span><span>Tłuszcz ${N(tot('fat'))} g</span></div>`)}${panel(`<h2>Wpisy w dzienniku</h2>${rows.map(x=>`<div class="dm-listrow"><strong>${e(x.name)}</strong><p class="dm-muted">${e(x.meal)} · ${N(x.calories)} kcal</p><div class="dm-actions">${select('Status','status-'+x.id,[['eaten','Zjedzone'],['planned','Zaplanowane'],['skipped','Pominięte']],x.status)}${btn('Usuń','delete-diary',x.id,'dm-link')}</div></div>`).join('')||empty('Oznacz zjedzony posiłek lub dopisz coś poza planem.')}`)}</aside></div>`}
function householdView(){return head('Domownicy',btn('＋ Dodaj','profile-new'))+`<div class="dm-stack">${S.profiles.map(x=>panel(`<div class="dm-between"><div><h2>${e(x.name)}</h2><p class="dm-muted">${x.calories?N(x.calories)+' kcal · ±'+N(x.tolerance_value)+(x.tolerance_type==='percent'?'%':' kcal'):'Bez limitu kalorii'}</p><p class="dm-muted">Porcja główna ×${N(x.portion_factor)} · ${x.participates?'wspólny plan':'poza generatorem'}</p></div>${btn('Edytuj','profile-edit',x.id,'dm-btn soft')}</div>`)).join('')}</div>`}
function goalsView(){const x=p(),c=x.calculation||{};return head('Twój cel',btn('Edytuj','profile-edit',x.id,'dm-btn soft'))+balanceCard()+panel(`<h2>${e(x.name)}</h2><div class="dm-setting"><strong>Cel masy ciała</strong><span>${x.target_weight?N(x.target_weight)+' kg':'Nie ustawiono'}</span></div><div class="dm-setting"><strong>Aktualna masa</strong><span>${x.weight?N(x.weight)+' kg':'—'}</span></div><div class="dm-setting"><strong>Termin</strong><span>${e(x.deadline||'Bez terminu')}</span></div><div class="dm-actions">${btn('Oszacuj kalorie','estimate',x.id)}${btn('Dodaj pomiar','weight-new','','dm-btn soft')}</div>`)+panel(`<h2>Szacunkowe wartości</h2><div class="dm-macros"><span>BMI <b>${c.bmi?N(c.bmi):'—'}</b></span><span>BMR <b>${c.bmr?N(c.bmr):'—'}</b></span><span>TDEE <b>${c.tdee?N(c.tdee):'—'}</b></span></div><p class="dm-muted dm-space">${e(c.warning||'Wzór Mifflina–St Jeora i mnożnik aktywności dają przybliżenie. Wynik wymaga Twojego zatwierdzenia. Zmiana wagi nie zmienia limitu kalorii.')}</p>`)}
function progressView(){const ws=S.weights.filter(x=>x.profile_id===p().id),values=ws.map(x=>Number(x.weight)),lo=Math.min(...values)-1,hi=Math.max(...values)+1,coords=values.map((v,i)=>`${30+(values.length>1?i/(values.length-1):.5)*320},${120-(v-lo)/(hi-lo)*90}`);const start=values[0],current=values.at(-1),goal=Number(p().target_weight||0),pct=goal&&start!==goal?Math.max(0,Math.min(100,(start-current)/(start-goal)*100)):0;return head('Masa i postępy',btn('＋ Pomiar','weight-new'))+panel(ws.length?`<h2>${N(current)} kg <span class="dm-muted">zmiana ${current-start>=0?'+':''}${N(current-start)} kg</span></h2><svg class="dm-weight-chart" viewBox="0 0 380 155" role="img" aria-label="Historia masy ciała"><path d="M30 125H355" stroke="var(--dm-line)"/><polyline points="${coords.join(' ')}" fill="none" stroke="currentColor" stroke-width="3"/>${coords.map(pt=>{const[x,y]=pt.split(',');return `<circle cx="${x}" cy="${y}" r="4" fill="currentColor"/>`}).join('')}<text x="20" y="148">${e(ws[0].date)}</text><text x="265" y="148">${e(ws.at(-1).date)}</text></svg><p class="dm-muted">${goal?'Cel '+N(goal)+' kg · postęp '+N(pct)+'%':'Ustaw docelową masę ciała w profilu.'}</p>`:empty('Dodaj pierwszy pomiar.'))+panel(ws.slice().reverse().map(w=>`<div class="dm-between dm-listrow"><span>${e(w.date)} · <b>${N(w.weight)} kg</b><small class="dm-muted"> ${e(w.note)}</small></span>${btn('Usuń','delete-weight',w.id,'dm-link')}</div>`).join(''))}
function productsView(){return head('Produkty i miary',btn('＋ Produkt','food-new'))+`<p class="dm-muted">Własna baza wartości na 100 g. Dostępność sezonową i postać produktu wykorzystuje generator.</p>`+panel(S.foods.map(x=>`<div class="dm-listrow"><div class="dm-between"><strong>${e(x.name)}</strong>${btn('Edytuj','food-edit',x.id,'dm-link')}</div><p class="dm-muted">${N(x.calories)} kcal / 100 g · ${e(x.measure)} = ${N(x.grams_each)} g · ${e(forms.find(a=>a[0]===x.form)?.[1])}</p><div class="dm-actions">${btn('Zjadłem','food-log',x.id,'dm-btn soft')}${btn('Usuń','delete-food',x.id,'dm-link')}</div></div>`).join('')||empty('Dodaj produkty, które jecie najczęściej.'))}
function collectionsView(){const tags=[...new Set(S.recipes.flatMap(r=>(r.tags||'').split(',').map(x=>x.trim()).filter(Boolean)))];return head('Kolekcje i tagi')+panel(['Ulubione',...tags].map(t=>btn(`${e(t)} <span>›</span>`,'collection',t,'dm-menu-row')).join('')||empty('Kolekcje powstają z tagów w przepisach.'))}
function rulesView(){return head('Reguły generatora',btn('＋ Reguła','rule-new'))+panel(`<h2>Domyślne planowanie</h2><p class="dm-muted dm-space">${meals.map(m=>`${m}: ${S.defaults.repeat_days[m]} dni, ${S.defaults.active_limits[m]||'bez limitu'} min pracy`).join(' · ')}</p><p class="dm-muted">Sezon: ${{prefer:'preferuj sezonowe',strict:'tylko sezonowe',off:'bez filtrowania'}[S.defaults.season_mode]}</p><div class="dm-actions">${btn('Zmień domyślne','defaults-edit','','dm-btn soft')}${btn('Przykład: weekend','weekend-rule','','dm-btn ghost')}</div>`)+`<p class="dm-muted dm-space">Najpierw domyślne ustawienia, potem pasujące reguły od niższego priorytetu do wyższego. Jednorazowe ustawienia generatora mają pierwszeństwo.</p>`+S.rules.map(r=>panel(`<div class="dm-between"><h2>${e(r.name)}</h2><span class="dm-badge">${r.enabled?'Aktywna':'Wyłączona'} · ${r.priority}</span></div><p class="dm-muted dm-space">${r.weekdays.length?r.weekdays.map(i=>['Pn','Wt','Śr','Cz','Pt','So','Nd'][i]).join(', '):'Wszystkie dni'} · ${e(r.seasons.join(', ')||'cały rok')} · ${e(r.start_date||'bez daty')} – ${e(r.end_date||'bez daty')}</p><div class="dm-actions">${btn('Edytuj','rule-edit',r.id,'dm-btn soft')}${btn('Usuń','delete-rule',r.id,'dm-link')}</div>`)).join('')}
function prepView(){const batches=[...new Map(S.meals.map(m=>[m.batch_id,m])).values()].sort((a,b)=>a.prepare_date.localeCompare(b.prepare_date));return head('Przygotowanie posiłków')+`<p class="dm-muted">Gotowanie ma własną datę. Jedna partia może pokrywać posiłki przez kilka dni.</p>`+batches.map(m=>{const events=S.meals.filter(x=>x.batch_id===m.batch_id),total=events.reduce((a,x)=>a+Object.values(x.portions).reduce((b,n)=>b+Number(n),0),0);return panel(`<div class="dm-between"><h2>${e(m.recipe.name)}</h2><span class="dm-badge">${m.prepared?'Gotowe':'Do zrobienia'}</span></div><p class="dm-muted dm-space">Gotowanie ${e(m.prepare_date)} · ${N(total)} porcji · ${e(m.cook_name||'nie przypisano osoby')}</p><p class="dm-muted">Jedzenie: ${[...new Set(events.map(x=>x.date))].join(', ')}</p><p>${e(m.note)}</p><div class="dm-actions">${btn('Gotuj','cook-batch',m.id)}${btn('Szczegóły','batch-edit',m.id,'dm-btn soft')}${btn(m.prepared?'Cofnij gotowe':'Oznacz gotowe','batch-ready',m.id,'dm-btn ghost')}</div>`)}).join('')}
function shoppingView(){return head('Lista zakupów',btn('＋ Lista','list-new'))+`<div class="dm-categories">${S.lists.map(l=>btn(e(l.name),'list',l.id,'dm-pill '+(l.id===listId?'active':''))).join('')}</div>`+(!shopping?empty('Utwórz listę i wybierz zakres dni.'):shopBody())}
function shopBody(){const q=shopping,changed=q.diff.added.length+q.diff.removed.length+q.diff.changed.length,groups=[...new Set(q.items.map(x=>x.category))];return `<p class="dm-muted">${e(q.list.start_date)} – ${e(q.list.end_date)}. Kupujesz składniki na całe partie gotowania przypadające na ten okres.</p>${changed?panel(`<h2>Zmiany w planie</h2><p class="dm-muted">Dodano ${q.diff.added.length}, usunięto ${q.diff.removed.length}, zmieniono ilość ${q.diff.changed.length}.</p><div class="dm-actions">${btn('Pokaż różnice','shop-diff','','dm-btn soft')}${btn('Zatwierdź zmiany','shop-sync')}</div>`):''}<div class="dm-actions">${btn('＋ Własny produkt','shop-manual','','dm-btn ghost')}${btn('Własne pozycje','shop-own','','dm-btn ghost')}${btn('Drukuj','print','','dm-btn ghost')}${btn('Usuń listę','delete-list',listId,'dm-link')}</div><div class="dm-shopping-grid">${groups.map(group=>`<section class="dm-shop-group"><h3>${e(group)}</h3>${panel(q.items.filter(x=>x.category===group).map(x=>`<div class="dm-shop-row ${x.status!=='needed'?'done':''}"><div><span class="dm-shop-name">${e(x.name)}</span><span class="dm-shop-qty">${N(x.quantity)} ${e(x.unit)}</span>${x.needs_review?'<p class="dm-danger">Ilość wzrosła — sprawdź, czy wystarczy.</p>':''}<small class="dm-muted">${e(x.sources.join(', '))}</small></div><select data-shop="${e(x.key)}" aria-label="Status ${e(x.name)}">${[['needed','Do kupienia'],['purchased','Kupione'],['home','Mam w domu']].map(([v,t])=>`<option value="${v}" ${v===x.status?'selected':''}>${t}</option>`).join('')}</select></div>`).join(''))}</section>`).join('')||empty('Brak składników w tym okresie.')}</div>`}
function settingsView(){return head('Ustawienia')+panel(`<div class="dm-setting"><div><strong>Domowe Menu ${e(S.version)}</strong><small>Dane i obliczenia na Twoim serwerze</small></div>${btn('Jasny / ciemny','theme','','dm-btn soft')}</div><div class="dm-stack dm-space">${btn('Pobierz pełną kopię','export')}${btn('Przywróć kopię Domowego Menu','restore','','dm-btn ghost')}${btn('Import przepisów z Mealie (ZIP)','import-mealie','','dm-btn ghost')}${btn('Import przepisu z adresu WWW','import-url','','dm-btn ghost')}${btn('Wyloguj','logout','','dm-btn ghost')}</div>`)+panel(`<h2>Aplikacja na iPhonie</h2><p class="dm-muted dm-space">Otwórz tę stronę przez HTTPS w Safari, wybierz Udostępnij → Do ekranu początkowego. Plan i zakupy wymagają połączenia z serwerem.</p><p class="dm-muted dm-space">Import Mealie przenosi przepisy, składniki tekstowe i instrukcje. Sprawdź porcje, typy posiłków, czasy i wartości odżywcze przed generowaniem planu.</p>`)}
function cookView(){const m=cookId?event(cookId):null,r=m?.recipe||recipe(recipeId);if(!r)return empty('Nie znaleziono przepisu.');const state=m?.cook_state?JSON.parse(m.cook_state):JSON.parse(localStorage.getItem('cook-'+r.id)||'{}');return head('Gotujemy',btn('Zamknij','nav',m?'prep':'detail','dm-btn ghost'))+panel(`<h2>${e(r.name)}</h2><p class="dm-muted">${m?'Kroki są zapisywane dla całej partii.':'Kroki zapamiętane na tym urządzeniu.'}</p><div class="dm-actions">${btn('Ustaw minutnik','timer','','dm-btn soft')}<span id="timer-label"></span></div>${(r.instructions||'').split('\n').filter(Boolean).map((s,i)=>`<label class="dm-check-step"><input type="checkbox" data-step="${i}" ${state[i]?'checked':''}><span><b>${i+1}.</b> ${e(s)}</span></label>`).join('')||empty('Uzupełnij instrukcję w przepisie.')}<div class="dm-actions">${m?btn('Oznacz przygotowane','batch-ready',m.id):''}</div>`)}
function recipeForm(id){const r=recipe(id)||{servings:2,ingredients:[],meal_types:['Obiad'],seasons:[]};form(id?'Edytuj przepis':'Nowy przepis',field('Nazwa','name',r.name,'text','required')+field('Ile porcji daje cały przepis?','servings',r.servings,'number','min="0.25" step="0.25" required')+field('Kategoria','category',r.category||'Obiad')+field('Tagi / kolekcje (po przecinku)','tags',r.tags)+checks('Pasuje jako','meal_types',[...meals,'Przekąska'],r.meal_types)+checks('Preferowany sezon (puste = cały rok)','seasons',seasons,r.seasons)+field('Aktywna praca (min)','active_minutes',r.active_minutes,'number','min="0"')+field('Łączny czas (min)','total_minutes',r.total_minutes,'number','min="0"')+['calories','protein','carbs','fat'].map((k,i)=>field(['kcal na jedną porcję','Białko g / porcję','Węgle g / porcję','Tłuszcz g / porcję'][i],k,r[k],'number','min="0" step="0.1"')).join('')+area('Składniki całego przepisu','ingredients',r.ingredients.map(i=>`${i.name} | ${i.qty} | ${i.unit} | ${i.grams_each||''} | ${i.form||'fresh'} | ${(i.months||[]).join(',')}`).join('\n'),'Każdy składnik w nowej linii: nazwa | ilość | miara | gramów w 1 miarze | postać | miesiące. Np. cukier | 1 | łyżeczka | 5. Postać: fresh, frozen, canned, jar, dried. Miesiące opcjonalnie: 5,6,7.')+`<div class="wide">${btn('Przelicz makro z lokalnej bazy produktów','recipe-nutrition','','dm-btn soft')}<p class="dm-muted">Wartości odżywcze zapisujesz na jedną porcję.</p></div>`+area('Kroki — każdy w nowej linii','instructions',r.instructions)+area('Opis / uwagi','notes',r.notes)+field('Zdjęcie JPG / PNG / WebP do 8 MB','cover','','file','accept="image/jpeg,image/png,image/webp"'),async(d,fd)=>{d.id=id||undefined;d.meal_types=fd.getAll('meal_types');d.seasons=fd.getAll('seasons');d.ingredients=d.ingredients.split('\n').filter(x=>x.trim()).map(line=>{const a=line.split('|').map(x=>x.trim());return {name:a[0],qty:a[1]===''||a[1]===undefined?1:Number(a[1].replace(',','.')),unit:a[2]||'porcja',grams_each:a[3]?Number(a[3].replace(',','.')):null,form:a[4]||'fresh',months:(a[5]||'').split(',').map(Number).filter(x=>x>=1&&x<=12)}});delete d.cover;const saved=await post('recipes',d),file=fd.get('cover');if(file?.size){const result=await fetch('/api/recipes/image?id='+saved.id,{method:'POST',headers:{'Content-Type':file.type},body:file});const res=await result.json();if(!result.ok)throw Error(res.error)}recipeId=saved.id;page='detail'})}
function profileForm(id){const x=S.profiles.find(x=>x.id==id)||{portion_factor:1,participates:1,tolerance_type:'percent',tolerance_value:5,rate:.25};form(id?'Profil domownika':'Dodaj domownika',field('Imię','name',x.name,'text','required')+select('Tryb celu','mode',[['manual','Ręczny'],['auto','Szacunek z zatwierdzeniem']],x.mode||'manual')+field('Zatwierdzony limit kcal (puste = wyłączony)','calories',x.calories,'number','min="0"')+select('Tolerancja','tolerance_type',[['percent','Procent'],['fixed','kcal']],x.tolerance_type)+field('Wartość tolerancji ±','tolerance_value',x.tolerance_value,'number','min="0" step="0.1"')+`<div class="wide dm-muted">Możesz wpisać 5 lub 10%, albo 50, 100, 150 kcal i dowolną własną wartość.</div>`+select('Płeć do wzoru','sex',[['','Nie podano'],['female','Kobieta'],['male','Mężczyzna']],x.sex)+field('Data urodzenia (opcjonalna)','birth_date',x.birth_date,'date')+field('Wiek, jeśli bez daty urodzenia','age_override',x.age_override,'number','min="1" max="120"')+field('Wzrost cm','height',x.height,'number','min="1" max="250" step="0.1"')+field('Aktualna masa kg','weight',x.weight,'number','min="1" max="500" step="0.1"')+field('Docelowa masa kg','target_weight',x.target_weight,'number','min="1" max="500" step="0.1"')+select('Aktywność','activity',[['sedentary','Siedząca'],['light','Lekka'],['moderate','Umiarkowana'],['high','Wysoka'],['very_high','Bardzo wysoka']],x.activity||'light')+select('Cel masy','goal',[['lose','Redukcja'],['maintain','Utrzymanie'],['gain','Zwiększenie']],x.goal||'maintain')+field('Tempo kg / tydzień','rate',x.rate,'number','min="0" max="1" step="0.05"')+field('Start','start_date',x.start_date,'date')+field('Termin celu','deadline',x.deadline,'date')+field('Stała porcja głównych dań ×','portion_factor',x.portion_factor,'number','min="0.25" max="3" step="0.25"')+field('Ograniczenia / alergeny, po przecinku','restrictions',x.restrictions)+['protein','carbs','fat'].map((k,i)=>field(['Cel białka g','Cel węgli g','Cel tłuszczu g'][i],k,x[k],'number','min="0"')).join('')+`<div class="wide">${checkbox('Uwzględniaj we wspólnym planie','participates',x.participates)}${checkbox('Ciąża — wyłącz kalkulator','pregnant',x.pregnant)}${checkbox('Karmienie piersią — wyłącz kalkulator','breastfeeding',x.breastfeeding)}${checkbox('Wymagam indywidualnych zaleceń — wyłącz kalkulator','individual_guidance',x.individual_guidance)}</div>`,async(d,fd)=>{d.id=id||undefined;for(const k of ['participates','pregnant','breastfeeding','individual_guidance'])d[k]=fd.has(k);const saved=await post('profiles',d);pid=saved.id;localStorage.setItem('profile',pid);page='goals'})}
function foodForm(id){const x=S.foods.find(x=>x.id==id)||{grams_each:1,measure:'g',form:'fresh',months:'[]'};form('Produkt i domowa miara',field('Nazwa','name',x.name,'text','required')+select('Postać','form',forms,x.form)+['calories','protein','carbs','fat'].map((k,i)=>field(['kcal / 100 g','Białko / 100 g','Węgle / 100 g','Tłuszcz / 100 g'][i],k,x[k]||0,'number','min="0" step="0.1"')).join('')+field('Miara domowa, np. łyżeczka','measure',x.measure)+field('Gramów w jednej mierze','grams_each',x.grams_each,'number','min="0.1" step="0.1"')+field('Grupa zamienników, np. pieczywo','group_name',x.group_name)+checks('Dostępność — puste = automatycznie / cały rok','months',Array.from({length:12},(_,i)=>[i+1,new Date(2026,i,1).toLocaleDateString('pl',{month:'short'})]),JSON.parse(x.months||'[]')),async(d,fd)=>{d.id=id||undefined;d.months=fd.getAll('months').map(Number);await post('foods',d)})}
function diaryForm(food){const x=S.foods.find(x=>x.id==food);form(x?'Zjedzony produkt':'Posiłek poza planem',(x?`<p class="wide">${e(x.name)} · ${N(x.calories)} kcal / 100 g</p>`:field('Nazwa / opis posiłku','name','','text','required')+`<p class="dm-muted wide">Wpisz wartości z etykiety lub dodaj produkt ze swojej bazy. Opis tekstowy sam nie wylicza kalorii.</p>`+['calories','protein','carbs','fat'].map((k,i)=>field(['kcal','Białko g','Węgle g','Tłuszcz g'][i],k,0,'number','min="0" step="0.1"')).join(''))+(x?field('Ilość gramów','grams',100,'number','min="0.1" step="0.1"'):'')+select('Posiłek','meal',[...meals,'Przekąska'],'Przekąska')+select('Status','status',[['eaten','Zjedzone'],['planned','Zaplanowane'],['skipped','Pominięte']],'eaten'),async d=>{if(x){d.name=x.name;d.food_id=x.id;for(const k of ['calories','protein','carbs','fat'])d[k]=Number(x[k])*Number(d.grams)/100}d.profile_id=p().id;d.date=day;await post('diary',d);page='diary'})}
function planForm(id,slot={}){form('Wspólny posiłek lub przekąska',select('Przepis','recipe_id',S.recipes.filter(r=>!r.archived).map(r=>[r.id,r.name]),id||recipeId)+field('Pierwszy dzień jedzenia','date',slot.date||day,'date','required')+field('Dzień gotowania','prepare_date',slot.date||day,'date','required')+field('Liczba dni z tej samej partii','days',1,'number','min="1" max="31"')+select('Rodzaj posiłku','meal',[...meals,'Przekąska'],slot.meal||'Obiad')+select('Osoba dla przekąski','profile_id',S.profiles.map(x=>[x.id,x.name]),p().id)+`<h3 class="wide">Porcje (0 = bez porcji)</h3>`+S.profiles.map(x=>field(x.name,'portion-'+x.id,x.participates?x.portion_factor:0,'number','min="0" max="6" step="0.25"')).join('')+field('Kto gotuje?','cook_name','')+area('Notatka','note',''),async d=>{d.recipe_id=Number(d.recipe_id);d.profile_id=d.meal==='Przekąska'?Number(d.profile_id):null;d.portions={};for(const x of S.profiles){if((!d.profile_id||d.profile_id===x.id)&&Number(d['portion-'+x.id])>0)d.portions[x.id]=Number(d['portion-'+x.id])}await post('meal',d);page='planner'})}
function configFields(config,inherit=false){return `<p class="wide dm-muted">${inherit?'Puste pola dziedziczą poprzednie ustawienie.':'Wartość 0 przy czasie wyłącza limit.'}</p>`+meals.map(m=>`<h3 class="wide">${m}</h3>${field('Gotowanie na ile dni','repeat-'+m,config.repeat_days?.[m]??(inherit?'':1),'number','min="1" max="31"')}${field('Maks. aktywna praca min','active-'+m,config.active_limits?.[m]??'','number','min="0"')}${field('Maks. łączny czas min','total-'+m,config.total_limits?.[m]??'','number','min="0"')}`).join('')+select('Sezonowość','season_mode',[...(inherit?[['','Dziedzicz']]:[]),['prefer','Preferuj sezonowe'],['strict','Tylko sezonowe'],['off','Bez filtrowania']],config.season_mode??'')+field('Odstęp między gotowaniami dania (dni)','min_gap',config.min_gap??'','number','min="0" max="60"')+field('Maks. nowych gotowań dania / tydzień','max_week',config.max_week??'','number','min="1" max="7"')+field('Maks. przekąsek na osobę / dzień','max_snacks',config.max_snacks??'','number','min="0" max="5"')+field('Wyklucz składniki (przecinki)','exclude_ingredients',(config.exclude_ingredients||[]).join(', '))+field('Wyklucz tagi (przecinki)','exclude_tags',(config.exclude_tags||[]).join(', '))+field('Preferuj tagi (przecinki)','preferred_tags',(config.preferred_tags||[]).join(', '))}
function configData(d,inherit=false){const out={repeat_days:{},active_limits:{},total_limits:{}};for(const m of meals)for(const [prefix,key]of [['repeat','repeat_days'],['active','active_limits'],['total','total_limits']])if(d[prefix+'-'+m]!=='')out[key][m]=Number(d[prefix+'-'+m]);for(const key of ['min_gap','max_week','max_snacks'])if(d[key]!=='')out[key]=Number(d[key]);if(d.season_mode)out.season_mode=d.season_mode;for(const key of ['exclude_ingredients','exclude_tags','preferred_tags'])if(!inherit||d[key])out[key]=d[key].split(',').map(x=>x.trim()).filter(Boolean);return out}
function ruleForm(id,weekend=false){const r=S.rules.find(x=>x.id===id)||{enabled:1,priority:20,weekdays:weekend?[5,6]:[],seasons:[],settings:weekend?{active_limits:{Śniadanie:40,Obiad:90,Kolacja:40},repeat_days:{Obiad:1}}:{}};form('Reguła cykliczna',field('Nazwa','name',r.name||(weekend?'Spokojny weekend':''),'text','required')+field('Priorytet (większy wygrywa)','priority',r.priority,'number','min="0"')+field('Od (opcjonalnie)','start_date',r.start_date,'date')+field('Do (opcjonalnie)','end_date',r.end_date,'date')+checks('Dni — puste = wszystkie','weekdays',['Pn','Wt','Śr','Cz','Pt','So','Nd'].map((n,i)=>[i,n]),r.weekdays)+checks('Pory roku — puste = wszystkie','seasons',seasons,r.seasons)+`<div class="wide">${checkbox('Reguła aktywna','enabled',r.enabled)}</div>`+configFields(r.settings,true),async(d,fd)=>{await post('planner_rules',{id:id||undefined,name:d.name,priority:d.priority,start_date:d.start_date,end_date:d.end_date,enabled:fd.has('enabled'),weekdays:fd.getAll('weekdays').map(Number),seasons:fd.getAll('seasons'),settings:configData(d,true)})})}
function generatorForm(){form('Ułóż rodzinny plan',field('Od','start_date',day,'date','required')+field('Do','end_date',shift(day,6),'date','required')+`<p class="dm-notice wide">Istniejące posiłki pozostają. Generator uzupełnia wolne miejsca, dopasowuje wspólną porcję i dodaje osobiste przekąski. Gotowy wynik pokaże przed zapisem.</p><details class="wide"><summary>Jednorazowe ustawienia (opcjonalne)</summary><div class="dm-form-grid">${configFields({},true)}</div></details>`,async d=>{proposal=await post('generate',{start_date:d.start_date,end_date:d.end_date,overrides:configData(d,true)});showProposal();return false},'Pokaż propozycję')}
function showProposal(){sheet('Propozycja planu',`<p class="dm-muted">${proposal.start_date} – ${proposal.end_date} · sprawdzono ${proposal.attempts} wariantów głównych dań</p>${proposal.days.map(d=>panel(`<strong>${e(d.date)}</strong><p class="dm-muted">${e(d.rules.join(' · ')||'Ustawienia domyślne')}</p>${proposal.entries.filter(x=>x.date===d.date).map(x=>`<p class="dm-listrow">${e(x.meal)} · ${e(recipe(x.recipe_id)?.name)}${x.profile_id?' · '+e(S.profiles.find(p=>p.id===x.profile_id)?.name):' · wspólne'}<small class="dm-muted"> ${Object.entries(x.portions).map(([id,v])=>e(S.profiles.find(p=>p.id==id)?.name)+': '+N(v)).join(', ')}</small></p>`).join('')}${d.balances.map(b=>`<p class="dm-muted">${e(b.name)}: ${N(b.actual)} kcal ${b.target?'('+N(b.low)+'–'+N(b.high)+')':''} · ${b.accepted?'✓':'poza zakresem'}</p>`).join('')}${!d.complete?'<p class="dm-danger">Brak pełnego zestawu dań.</p>':''}`)).join('')}${proposal.warnings.map(w=>`<p class="dm-warning dm-space">${e(w)}</p>`).join('')}<div class="dm-actions dm-space">${btn('Zatwierdź propozycję','approve')}${btn('Zmień ustawienia','generator','','dm-btn ghost')}</div>`)}
async function swapForm(id){const m=event(id),config=S.defaults;const alternatives=S.recipes.filter(r=>!r.archived&&r.id!==m.recipe_id&&r.meal_types.includes(m.meal));sheet('Wybierz zamianę',`<p class="dm-muted">Zamiana dotyczy tego posiłku jednego dnia. Porcje pozostają te same. Sprawdź składniki i ograniczenia domowników przed zatwierdzeniem.</p>${alternatives.map(r=>{const qty=Number(m.portions[p().id]||0),value=totalPlan()+(Number(r.calories)-Number(m.recipe.calories))*qty,b=balance(value);return panel(`<h3>${e(r.name)}</h3><p class="dm-muted">${N(r.calories)} kcal / porcję · dzień ${N(value)} kcal · ${b.accepted?'w zakresie':'poza zakresem'} · różnica posiłku ${N((r.calories-m.recipe.calories)*qty)} kcal</p>${btn('Wybierz','swap-confirm',id+'|'+r.id,'dm-btn soft')}`)}).join('')||empty('Dodaj inne przepisy tego typu.')}`)}
async function estimate(id){const result=await post('estimate',{id:Number(id)});if(!result.suggested){sheet('Szacowanie zapotrzebowania',`<p>${e(result.warning||'Uzupełnij wiek, wzrost, masę ciała i płeć w profilu.')}</p>`);return}form('Zatwierdź szacunkowy cel',`<p class="wide dm-notice">BMI ${N(result.bmi)} · BMR ${N(result.bmr)} · TDEE ${N(result.tdee)} kcal. To przybliżenie dla osoby dorosłej. Możesz skorygować wynik przed zapisaniem.</p>`+field('Dzienny cel kcal','calories',result.suggested,'number','min="1" required'),async d=>{await post('profiles',{id:Number(id),calories:d.calories,mode:'auto'})},'Zatwierdź limit')}
function menu(){sheet('Twoja kuchnia',[['Przepisy','recipes'],['Kolekcje','collections'],['Plan rodzinny','planner'],['Przygotowanie','prep'],['Dziennik','diary'],['Cele żywieniowe','goals'],['Masa i postępy','progress'],['Produkty i miary','products'],['Domownicy','household'],['Reguły generatora','rules'],['Ustawienia i kopie','settings']].map(([t,id])=>btn(`${t}<span>›</span>`,'nav',id,'dm-menu-row')).join(''))}
function pickImport(kind){importKind=kind;$('#import-file').accept=kind==='mealie'?'.zip':'.json';$('#import-file').value='';$('#import-file').click()}
async function remove(table,id,label){if(!confirm(label||'Usunąć ten wpis?'))return;await api('/api/v1/'+table+'?id='+encodeURIComponent(id),null,'DELETE');await load()}
let timerEnd=0,timerInterval=null;
async function action(a,id,el){switch(a){
case 'reload':location.reload();break;
case 'close':$('#dialog').close();break;
case 'nav':if(id==='add'){sheet('Dodaj do swojej kuchni',[['Przepis','recipe-new'],['Posiłek do planu','plan-new'],['Posiłek poza planem','diary-new'],['Pomiar masy','weight-new'],['Produkt','food-new']].map(([t,a])=>btn(t,a,'','dm-menu-row')).join(''));break}go(id);if(id==='shopping'&&S.lists.length){listId=listId||S.lists[0].id;await load()}break;
case 'menu':menu();break;
case 'theme':{const next=document.body.dataset.theme==='dark'?'light':'dark';document.body.dataset.theme=next;localStorage.setItem('theme',next);break}
case 'date':day=id;await load();break;
case 'date-shift':if(id.startsWith('month:')){const d=new Date(day+'T12:00:00');d.setDate(1);d.setMonth(d.getMonth()+Number(id.split(':')[1]));day=iso(d)}else day=shift(day,Number(id));await load();break;
case 'calendar-mode':month=!month;render();break;
case 'filter':if(meals.includes(id)||id==='Przekąska'){collection='';search=id;go('recipes')}else{collection=id;search='';render()}break;
case 'collection':collection=id;search='';go('recipes');break;
case 'detail':if(!id||id==='null'){toast('Przepis został usunięty.');break}recipeId=Number(id);detailPortions=Number(recipe(id)?.servings||1);go('detail');break;
case 'portion':detailPortions=Math.max(.5,detailPortions+Number(id));render();break;
case 'recipe-new':recipeForm();break;
case 'recipe-nutrition':{const formEl=$('#editor'),fd=new FormData(formEl),rows=String(fd.get('ingredients')).split('\n').filter(x=>x.trim()),sum={calories:0,protein:0,carbs:0,fat:0},unknown=[];for(const line of rows){const a=line.split('|').map(x=>x.trim()),food=S.foods.find(x=>x.name.toLocaleLowerCase('pl')===a[0].toLocaleLowerCase('pl')&&x.form===(a[4]||'fresh'));let grams=Number((a[1]||'1').replace(',','.'));if(a[3])grams*=Number(a[3].replace(',','.'));else if(a[2]==='kg')grams*=1000;else if(a[2]!=='g'){if(food&&food.measure===a[2])grams*=Number(food.grams_each)||NaN;else grams=NaN}if(!food||!Number.isFinite(grams)){unknown.push(a[0]);continue}for(const key in sum)sum[key]+=Number(food[key])*grams/100}if(unknown.length)throw Error('Uzupełnij produkty / miary: '+unknown.join(', '));const portions=Number(fd.get('servings'));if(!portions)throw Error('Ustaw liczbę porcji');for(const key in sum)formEl.elements[key].value=Math.round(sum[key]/portions*10)/10;toast('Przeliczono wartości na porcję. Zapisz przepis.');break;}
case 'recipe-edit':recipeForm(Number(id));break;
case 'favorite':await post('recipes',{id:Number(id),favorite:!recipe(id).favorite});await load();break;
case 'archive':if(confirm(recipe(id).archived?'Przywrócić przepis z archiwum?':'Przenieść przepis do archiwum? Pozostanie w zapisanych planach.')){await post('recipes',{id:Number(id),archived:!recipe(id).archived});go('recipes');await load()}break;
case 'profile-new':profileForm();break;
case 'profile-edit':profileForm(Number(id));break;
case 'estimate':await estimate(id);break;
case 'weight-new':form('Nowy pomiar · '+p().name,field('Data pomiaru','date',day,'date','required')+field('Masa kg','weight',p().weight||'','number','min="1" max="500" step="0.1" required')+field('Notatka','note',''),async d=>{await post('weight',{...d,profile_id:p().id});page='progress'});break;
case 'food-new':foodForm();break;
case 'food-edit':foodForm(Number(id));break;
case 'delete-manual':await remove('shopping_manual',id);$('#dialog').close();break;
case 'food-log':diaryForm(Number(id));break;
case 'diary-new':diaryForm();break;
case 'plan-slot':{const [date,meal]=id.split('|');planForm(undefined,{date,meal});break;}
case 'week-meal':{const m=event(id);if(m)sheet(m.date+' · '+m.meal,mealCard(m));break;}
case 'plan-new':case 'plan-recipe':planForm(Number(id)||undefined);break;
case 'eat':case 'skip':await post('log-meal',{id,profile_id:p().id,status:a==='eat'?'eaten':'skipped'});await load();break;
case 'copy-day':if(confirm('Skopiować posiłki z poprzedniego dnia jako nowe gotowanie? Zajęte miejsca zablokują kopiowanie.')){await post('copy-day',{source:shift(day,-1),target:day});await load()}break;
case 'delete-meal':await remove('family_meals',id,'Usunąć ten posiłek tego dnia? Pozostałe dni tej partii pozostaną.');break;
case 'delete-diary':await remove('diary',id);break;
case 'delete-weight':await remove('weigh_ins',id);break;
case 'delete-food':await remove('foods',id);break;
case 'delete-rule':await remove('planner_rules',id);break;
case 'delete-list':await remove('shopping_lists',id);shopping=null;listId=null;render();break;
case 'swap':await swapForm(id);break;
case 'swap-confirm':{const[mid,rid]=id.split('|');await post('swap',{id:mid,recipe_id:Number(rid)});$('#dialog').close();await load();break}
case 'batch-edit':{const m=event(id);form('Szczegóły gotowania',field('Gotowanie dnia','prepare_date',m.prepare_date,'date','required')+field('Osoba gotująca','cook_name',m.cook_name)+area('Notatka','note',m.note),async d=>{await post('batch',{id:m.batch_id,...d})});break}
case 'batch-ready':{const m=event(id);await post('batch',{id:m.batch_id,prepared:!m.prepared});await load();break}
case 'cook-batch':cookId=id;go('cook');break;
case 'cook-recipe':cookId=null;recipeId=Number(id);go('cook');break;
case 'timer':form('Minutnik',field('Minuty','minutes',10,'number','min="1" max="600" required'),async d=>{timerEnd=Date.now()+Number(d.minutes)*60000;clearInterval(timerInterval);timerInterval=setInterval(()=>{const left=Math.max(0,Math.ceil((timerEnd-Date.now())/1000));if($('#timer-label'))$('#timer-label').textContent=Math.floor(left/60)+':'+String(left%60).padStart(2,'0');if(!left){clearInterval(timerInterval);toast('Minutnik: czas minął');navigator.vibrate?.([200,100,200])}},1000)});break;
case 'generator':generatorForm();break;
case 'approve':await post('approve',{id:proposal.id});$('#dialog').close();page='planner';await load();toast('Zapisano plan rodzinny');break;
case 'defaults-edit':form('Domyślne ustawienia generatora',configFields(S.defaults),async d=>{await post('defaults',configData(d))});break;
case 'rule-new':ruleForm();break;
case 'rule-edit':ruleForm(id);break;
case 'weekend-rule':ruleForm(null,true);break;
case 'list-new':form('Nowa lista zakupów',field('Nazwa','name','Zakupy na tydzień','text','required')+field('Od dnia','start_date',day,'date','required')+field('Do dnia','end_date',shift(day,6),'date','required'),async d=>{const saved=await post('shopping_lists',d);listId=saved.id;shopping=await api('/api/v1/shopping?id='+listId)});break;
case 'list':listId=id;shopping=await api('/api/v1/shopping?id='+id);render();break;
case 'shop-manual':form('Dopisz do zakupów',field('Produkt','name','','text','required')+field('Ilość','quantity',1,'number','min="0.1" step="0.1" required')+field('Jednostka','unit','szt.')+field('Dział','category','Inne'),async d=>{await post('shopping_manual',{...d,list_id:listId})});break;
case 'shop-own':sheet('Własne pozycje listy',shopping.manual.map(x=>`<div class="dm-between dm-listrow"><span>${e(x.name)} · ${N(x.quantity)} ${e(x.unit)}</span>${btn('Usuń','delete-manual',x.id,'dm-link')}</div>`).join('')||empty('Nie dopisano własnych pozycji.'));break;
case 'shop-sync':await post('shopping-sync',{id:listId});await load();break;
case 'shop-diff':sheet('Zmiany na liście zakupów',Object.entries(shopping.diff).map(([k,items])=>panel(`<h3>${{added:'Dodano',removed:'Usunięto',changed:'Zmieniono ilość'}[k]}</h3>${items.map(x=>`<p class="dm-listrow">${e((x.after||x).name)} · ${x.before?N(x.before.quantity)+' → ':''}${N((x.after||x).quantity)} ${e((x.after||x).unit)}</p>`).join('')||empty('Brak zmian')} `)).join(''));break;
case 'export':location.href='/api/v1/export';break;
case 'restore':if(confirm('Przywrócenie zastąpi dane Domowego Menu. Pobierz wcześniej aktualną kopię. Kontynuować?'))pickImport('restore');break;
case 'import-mealie':pickImport('mealie');break;
case 'import-url':form('Import przepisu z WWW',field('Publiczny adres przepisu','url','','url','required')+`<p class="dm-muted wide">Strona musi zawierać dane Recipe w Schema.org. Po imporcie sprawdź składniki, porcje i wartości odżywcze.</p>`,async d=>{const r=await api('/api/import-url',d);recipeId=r.id;page='detail'});break;
case 'logout':await api('/api/logout',{});login();break;
case 'print':window.print();break;
}}
document.addEventListener('click',async ev=>{const el=ev.target.closest('[data-a]');if(!el)return;try{el.disabled=true;await action(el.dataset.a,el.dataset.id,el)}catch(err){toast(err.message)}finally{el.disabled=false}});
document.addEventListener('submit',async ev=>{ev.preventDefault();const formEl=ev.target,button=formEl.querySelector('[type=submit]');if(button)button.disabled=true;try{const fd=new FormData(formEl),d=Object.fromEntries(fd);if(formEl.id==='login-form'){await api('/api/login',{password:d.password});await load();return}if(formEl.id==='editor'){const result=await formCallback(d,fd);if(result!==false){$('#dialog').close();await load();toast('Zapisano')}}}catch(err){const target=formEl.querySelector('[data-error]');if(target)target.textContent=err.message;else toast(err.message)}finally{if(button)button.disabled=false}});
document.addEventListener('change',async ev=>{const el=ev.target;try{if(el.id==='profile-select'){pid=Number(el.value);localStorage.setItem('profile',pid);render()}else if(el.name==='diary-date'){day=el.value;await load()}else if(el.name?.startsWith('status-')){await post('diary-status',{id:Number(el.name.slice(7)),status:el.value});await load()}else if(el.dataset.shop){await post('shopping-flag',{list_id:listId,key:el.dataset.shop,status:el.value});await load()}else if(el.dataset.step!==undefined){const m=cookId?event(cookId):null,r=m?.recipe||recipe(recipeId),state=Object.fromEntries($$('[data-step]').map(x=>[x.dataset.step,x.checked]));if(m){await post('batch',{id:m.batch_id,cook_state:state});m.cook_state=JSON.stringify(state)}else localStorage.setItem('cook-'+r.id,JSON.stringify(state))}}catch(err){toast(err.message)}});
document.addEventListener('input',ev=>{if(ev.target.id==='search'){search=ev.target.value;const pos=ev.target.selectionStart;render();$('#search').focus();$('#search').setSelectionRange(pos,pos)}});
$('#import-file').addEventListener('change',async ev=>{const file=ev.target.files[0];if(!file)return;try{toast('Wczytywanie pliku…');if(importKind==='mealie'){const response=await fetch('/api/import-mealie',{method:'POST',body:file});const r=await response.json();if(!response.ok)throw Error(r.error);toast('Zaimportowano '+r.imported+' przepisów. Sprawdź ich dane.')}else{await post('restore',JSON.parse(await file.text()));toast('Przywrócono dane')}$('#dialog').close();await load()}catch(err){toast(err.message)}});
function login(){document.body.dataset.auth='false';document.body.dataset.page='login';$('#sidebar').innerHTML='';$('#top').innerHTML='<span class="dm-brand">Domowe Menu</span>';$('#nav').innerHTML='';$('#main').innerHTML=`<section class="dm-hero"><div class="dm-hero-content"><p>Twoja rodzinna kuchnia</p><h1>Dobrze być w domu.</h1><p>Przepisy, plan i zakupy w jednym miejscu.</p></div></section>${panel(`<form id="login-form"><h2>Zaloguj się</h2>${field('Hasło rodziny','password','','password','required autocomplete="current-password"')}<div data-error class="dm-error" role="alert"></div><button class="dm-btn full" type="submit">Wejdź do kuchni</button></form>`)}`}
document.body.dataset.theme=localStorage.getItem('theme')||(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light');
if('serviceWorker'in navigator)navigator.serviceWorker.register('/static/sw.js',{scope:'/'}).catch(()=>{});
(async()=>{try{const session=await api('/api/session');if(session.authenticated)await load();else login()}catch(err){$('#main').innerHTML=panel(`<h2>Nie udało się połączyć</h2><p class="dm-muted">${e(err.message)}</p>${btn('Spróbuj ponownie','reload')}`)}})();
